{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Salbutamol, which shares the saligenin beta-agonist core with the query, has an absolute oral bioavailability of 44% in healthy volunteers, showing that this core alone can be consistent with F ≥ 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Epanolol, a beta-adrenoceptor ligand with a similar aryloxypropanolamine/phenolic structure, has an absolute oral bioavailability of only 7.06% in fasted volunteers, attributed to extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Terfenadine, a lipophilic amine with a large aromatic/hydrophobic structure, has an oral bioavailability of <2% in humans due to extensive first-pass metabolism, supporting that the query's long lipophilic amino-ether dichlorobenzyl tail will also undergo extensive presystemic clearance.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Phenylephrine, a phenolic beta-agonist with a beta-hydroxyethylamine motif, has poor oral bioavailability in healthy volunteers due to first-pass metabolism, supporting low F for the query's phenolic beta-agonist head group.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Bambuterol, a beta2-agonist-related molecule with phenolic groups and a beta-hydroxyamine, has about 10% oral bioavailability in healthy adults, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Hydroxytyrosol, a phenolic compound with a hydroxymethyl/ethanol motif, has only 6.2% oral bioavailability in humans, illustrating extensive phenolic conjugation and first-pass metabolism.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a vilanterol-like long-acting beta2 agonist with a saligenin head and a long lipophilic amino-ether dichlorobenzyl tail. Although salbutamol shows ~44-50% oral bioavailability, the query's extended lipophilic tail and dichlorobenzyl ether are expected to cause extensive first-pass metabolism and low systemic availability, consistent with multiple close analogues (epanolol ~7%, bambuterol ~10%, phenylephrine poor, terfenadine <2%). Therefore predict low (<20%).",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for the query molecule itself.",
    "Salbutamol high-F evidence lacks the long lipophilic tail and dichlorobenzyl ether that dominate the query's disposition.",
    "No specific metabolic stability or absorption data for the query's long amino-ether linker."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

